-- Excel review queue 2026-10-23, batch 14: the rest of the "Verify facts / meaning" rows.
-- Decisions taken by a person on 2026-10-24; research recorded in the PR.
--
--   * Micro-labels: 23 definitions corrected against the community sources that coined them
--     (LGBTQIA+ Wiki, MOGAI Wiki, coining posts); 13 kept; aposexual, switchuationship and
--     the-question-of-gender deprecated (no attestation / a book title); heterotypical deprecated
--     (a sexology adjective, not an identity label).
--   * Factual claims: 11 entries corrected (ureaplasma testing advice, jogappa regions,
--     nadleehi wording, lavender-rhinoceros, lip-sync-assassins moved to Drag & Performance,
--     captain's wrong identifier Q19100 = army rank cleared ...); 8 kept; 11 deprecated
--     (no attested meaning, or out of scope: zoophilia, spongeworthy, partners-in-mischief).
--   * 17 kink-persona tags whose only uses were accidental word matches (angel on "Angel
--     Season 5", maestro on an Oscars article ...) are deprecated and those wrong assignments
--     deleted. Deprecation also stops the nightly reconcile re-adding them, because it only
--     resolves active tags. lgbtq-unknown, an empty import placeholder, is treated the same.
--   * Used place and venue tags keep their definitions, which match what is tagged. Four are
--     corrected to the place their venues are in (pi-state = Piauí, wustrow, victoria-island,
--     salvador-lgbtq). Sentences addressed to editors ("should be confirmed", "a reviewer
--     should check") are removed with replace(); every other sentence stays byte-identical.
--   * bestiality is deprecated and its 4 news assignments deleted, for the same reason as
--     zoophilia: it is not queer or kink vocabulary, and a page for it echoes an old slur.
--   * decoration is merged into interior-design; hellpuppy, microphone, spill and tinkerbelle
--     are deprecated (unused, no active tag to merge into).
--
-- Left pending: anthropologist, attila-horbiger, clown, conductor, jan-mikolasek — other tags
-- are merged into them, so they cannot be deprecated without a separate decision.
-- pirate is also a merge target, so it stays active and its row is closed as checked.

select set_config('app.actor', 'migration:99991792852555_tag_review_batch14_verify_used', true);

update public.unified_tags set short_description = $t$Enjoys receiving sexual acts, not performing them$t$, description = $t$An alternative name for iamvanosexual: someone who enjoys having sexual acts performed on them but does not want to perform sexual acts on others.$t$, long_description = $t$Accipiosexual is a rare online micro-label and a synonym of iamvanosexual, which sits under the merosexual umbrella. It describes a sex stance rather than who someone is attracted to: the person welcomes being on the receiving end of sexual acts and is indifferent, averse or repulsed when it comes to performing them. People who use it may be on or off the asexual spectrum. Its opposite is placiosexual.$t$ where slug = 'accipiosexual' and status = 'active';
update public.unified_tags set short_description = $t$Attraction mainly to men, masc, andro and nb genders$t$, description = $t$A multisexual micro-label, also called verian, for primary sexual attraction to male-, masculine-, androgynous- and nonbinary-aligned genders, with occasional minor attraction to female- and feminine-aligned genders.$t$, long_description = $t$Almondsexual is a rare online micro-label on the multisexual spectrum. The person is drawn mainly to men and to masculine, androgynous and nonbinary-aligned genders, with only occasional, minor attraction to women and feminine-aligned genders. Its counterpart is berrisexual, and the romantic equivalent is almondromantic. The term and flag circulated on Pinterest and were archived on Tumblr in 2023.$t$ where slug = 'almondsexual' and status = 'active';
update public.unified_tags set short_description = $t$Knowing one gender fits but using another label$t$, description = $t$A gender identity in which someone knows a certain gender is correct for them but feels more comfortable identifying as a different gender.$t$, long_description = $t$Anesigender is a rare online micro-label coined on Tumblr in 2016. A person might know they are demigirlflux, for example, but identify as nonbinary or as a girl to avoid confusion or repeated explanations. The prefix comes from the Greek word for comfort. The sexuality counterpart is anesisexual.$t$ where slug = 'anesigender' and status = 'active';
update public.unified_tags set short_description = $t$Romantic attraction only after another attraction$t$, description = $t$An aromantic-spectrum romantic orientation in which romantic attraction is felt only after another form of attraction has developed.$t$, long_description = $t$Apresromantic is a rare online micro-label; the name comes from the French après, after. The first attraction may be aesthetic, sensual, platonic or another kind, and it may fade or be replaced once romantic attraction appears. It resembles demiromantic but turns on a prior attraction rather than an emotional bond. The sexual equivalent is apressexual.$t$ where slug = 'apresromantic' and status = 'active';
update public.unified_tags set short_description = $t$Micro-label with two meanings: aura or long cycles$t$, description = $t$A rare online micro-label with two meanings: attraction to a person's perceived aura or energy regardless of gender, or long periods of sexual attraction broken by short periods without it.$t$, long_description = $t$Aurasexual is used in two unrelated ways. On Tumblr and Urban Dictionary it names attraction to someone's aura or energy, similar to pansexual in that gender plays no part. On Reddit flag communities it names a fluctuating pattern: long stretches of sexual attraction with short stretches of none. Neither meaning has a documented coiner.$t$ where slug = 'aurasexual' and status = 'active';
update public.unified_tags set short_description = $t$Romantic attraction to kindness$t$, description = $t$A romantic-orientation micro-label for romantic attraction to kindness, including kind people and acts of kindness.$t$, long_description = $t$Benignoromantic is a rare online micro-label, from the Latin benignus, kind. It describes romantic attraction that is sparked by kindness and compassion rather than by a partner's gender or appearance. Its sexual counterpart is benignosexual.$t$ where slug = 'benignoromantic' and status = 'active';
update public.unified_tags set short_description = $t$Sexual attraction to kindness$t$, description = $t$A micro-label for sexual or romantic attraction to kindness, including kind people and acts of kindness.$t$, long_description = $t$Benignosexual is a rare online micro-label, from the Latin benignus, kind. It describes attraction that is drawn out by kindness and compassionate actions rather than by a partner's gender or looks. Its romantic counterpart is benignoromantic.$t$ where slug = 'benignosexual' and status = 'active';
update public.unified_tags set short_description = $t$Bi attraction shifting between genders over time$t$, description = $t$A term in bisexual communities for a bisexual person's attraction shifting in strength between genders over time.$t$, long_description = $t$Bi-cycle is a pun on bicycle used widely in bi communities for periods of being drawn more to one gender, then another. It is a common part of many bi people's experience. Being in one phase of the cycle does not mean a person has become gay or straight.$t$ where slug = 'bi-cycle' and status = 'active';
update public.unified_tags set short_description = $t$Attraction based on relative power$t$, description = $t$A micro-label for sexual attraction based on how a person's power compares with one's own.$t$, long_description = $t$Cratosexual, from the Greek kratos, power, was coined in 2014 on the Spanish AVENes AsexualpediA. The power can be physical, intellectual, economic, political or subjective. Related terms are hypercratic (attraction to people with less power), hypocratic (to people with more) and equicratic (to equal power). It is a rare online micro-label.$t$ where slug = 'cratosexual' and status = 'active';
update public.unified_tags set short_description = $t$Liking someone without full romantic attraction$t$, description = $t$An aromantic-spectrum micro-label for people who do not feel full romantic attraction but may feel 'liking' someone, which goes no further.$t$, long_description = $t$Desinoromantic was coined on Tumblr and DeviantArt in 2015; the name is from the Latin desino, I stop. People who use it may describe their feeling as liking someone but not loving them, and that liking is where the attraction ends. They may feel other kinds of attraction, such as alterous attraction. The sexual counterpart is desinosexual.$t$ where slug = 'desinoromantic' and status = 'active';
update public.unified_tags set short_description = $t$Enjoys receiving sexual acts, not performing them$t$, description = $t$A micro-label under the merosexual umbrella for someone who enjoys having sexual acts performed on them but does not want to perform sexual acts on others.$t$, long_description = $t$Iamvanosexual, also spelled lamvanosexual and also called accipiosexual, was coined in 2015; the root is the Ancient Greek for 'I receive'. It is a sex stance rather than an orientation: the person may be indifferent, averse or repulsed when it comes to performing sexual acts, sometimes because of dysphoria. Its opposite is placiosexual.$t$ where slug = 'iamvanosexual' and status = 'active';
update public.unified_tags set short_description = $t$Needing kink for sexual arousal$t$, description = $t$A label, also called kink-exclusive or obligate kinky, for someone who needs kink for sexual arousal, engagement or satisfaction.$t$, long_description = $t$Kinksexual is used by people for whom kink is not optional but a condition of sexual interest. It can sit alongside any gender attraction: a kinksexual person may be straight, gay or bi and look for partners who share their kinks. It is a rare online label.$t$ where slug = 'kinksexual' and status = 'active';
update public.unified_tags set short_description = $t$Romantic seducer; also a trafficking grooming method$t$, description = $t$Slang for a romantic, smooth-talking man, and the name of a trafficking method in which an exploiter poses as a boyfriend to groom young people into sexual exploitation.$t$, long_description = $t$In everyday English a lover boy is a charming, flirtatious seducer. In the Netherlands and across Europe, loverboy (also Romeo pimp) names traffickers who win a young person's affection, often over months and increasingly online, and then exploit them in the sex industry through dependence, blackmail or violence. Victims include boys as well as girls.$t$ where slug = 'lover-boy' and status = 'active';
update public.unified_tags set short_description = $t$Romantic attraction only after sexual chemistry$t$, description = $t$A label for people who do not feel emotional or romantic attraction to someone until sexual compatibility and chemistry are established.$t$, long_description = $t$Megasexual was coined by Dr Liz Powell and Rebecca Jay at Atlanta Poly Weekend in 2015. It is often described as the reverse of demisexual: the sexual connection comes first and any romantic bond follows it, if at all. Some users stress a lack of romantic connection. The flag inverts the demisexual flag's colours.$t$ where slug = 'megasexual' and status = 'active';
update public.unified_tags set short_description = $t$Attraction that changes day to day or with context$t$, description = $t$A fluid sexuality in which attraction changes from day to day, or with circumstances such as the people around, one's current gender, surroundings or mood.$t$, long_description = $t$Mutosexual was coined in 2020 by The Ragamuffins System; the name is from the Latin muto, change. Someone might be drawn to women one day, men the next and nonbinary people another. It is related to abrosexual, novosexual and expecsexual, and is sometimes treated as the orientation equivalent of mutogender. It is a rare online micro-label.$t$ where slug = 'mutosexual' and status = 'active';
update public.unified_tags set short_description = $t$Holding several ace-spectrum identities at once$t$, description = $t$An asexual-spectrum label for someone who experiences several ace-spectrum identities, such as being both demisexual and greysexual.$t$, long_description = $t$Myrsexual was coined on Tumblr in 2015; myr- means many. The identities can be steady or can fluctuate, which makes it similar to aceflux, though a myrsexual person does not always move between labels. The romantic equivalent is myrromantic.$t$ where slug = 'myrsexual' and status = 'active';
update public.unified_tags set short_description = $t$Attraction to people who use neopronouns$t$, description = $t$A micro-label for being attracted only to people who use neopronouns, regardless of their gender.$t$, long_description = $t$Neosexual is a rare online micro-label and a type of pronounsexual, defined by the pronouns of the people someone is drawn to rather than their gender. Its flag, made in 2020, combines colours from the genderqueer and asexual flags. Documentation is thin and no coiner is recorded.$t$ where slug = 'neosexual' and status = 'active';
update public.unified_tags set short_description = $t$Gender that changes with who one is around$t$, description = $t$A gender that changes depending on the people one is around; also called expecgender or swivelgender.$t$, long_description = $t$Pivotgender is a rare online micro-label first posted with its flag in 2016. It is a type of mutogender: the person's gender shifts in response to their company. Its orientation counterpart is pivotsexual, also called expecsexual.$t$ where slug = 'pivotgender' and status = 'active';
update public.unified_tags set short_description = $t$Orientation that changes with who one is around$t$, description = $t$A sexual orientation that changes depending on the people one is around; also called expecsexual or swivelsexual.$t$, long_description = $t$Pivotsexual is a rare online micro-label and a type of mutosexuality. The person's orientation shifts in response to their company rather than over time on its own. Its gender counterpart is pivotgender.$t$ where slug = 'pivotsexual' and status = 'active';
update public.unified_tags set short_description = $t$Prefers pornography to sex with partners$t$, description = $t$A label for someone who is aroused by and attracted to pornography more than to in-person sex with other people.$t$, long_description = $t$Pornosexual spread through media coverage around 2017 and is used both as a self-label and, by addiction clinics, as a description of problematic porn use. It is distinct from asexuality. The similar-sounding spornosexual, coined by Mark Simpson in 2014, is a different term for men who display gym-built bodies in a porn-influenced style.$t$ where slug = 'pornosexual' and status = 'active';
update public.unified_tags set short_description = $t$Attraction limited by emotional exhaustion$t$, description = $t$An asexual-spectrum label, usually spelled requiessexual, for limited or no sexual attraction, interest or activity because of emotional exhaustion.$t$, long_description = $t$Requiessexual was coined on Tumblr in 2014; requies is Latin for rest. The exhaustion may come from past sexual experiences or from anything else emotionally draining. The romantic counterpart is requiesromantic, and the two share a flag made in 2014, whose post used the spelling requissexual.$t$ where slug = 'requissexual' and status = 'active';
update public.unified_tags set short_description = $t$Attraction to a person's inner self$t$, description = $t$A micro-label for attraction to a person's inner self or soul rather than to their physical traits or gender.$t$, long_description = $t$Soulsexual is a rare online label. People who use it say what draws them is someone's whole being or personality, not appearance or gender, which overlaps with pansexual. Unlike demisexual, it does not require an established emotional bond before attraction appears.$t$ where slug = 'soulsexual' and status = 'active';
update public.unified_tags set short_description = $t$Wolffian ducts; also a term for male-typical sex$t$, description = $t$Relating to the Wolffian ducts, embryonic structures that develop into male internal reproductive organs, and a community term used in place of 'biological male'.$t$, long_description = $t$Under testosterone, the Wolffian ducts develop into the epididymis, vas deferens and seminal vesicles; otherwise they mostly regress. Online trans and intersex communities also use wolffian, popularised on Tumblr in 2018, for the sex traits of someone with testes exposed mainly to testosterone before birth, as an alternative to 'biological male'. It is not the same as AMAB, since some AMAB people are intersex, and its counterpart is müllerian.$t$ where slug = 'wolffian' and status = 'active';
update public.unified_tags set short_description = $t$Drag slang: it's true, and I don't mind if it stings$t$, description = $t$Drag slang said with a blunt remark, meaning the statement is true and the speaker does not mind if it offends.$t$, long_description = $t$The phrase plays on two staples of drag and ballroom slang: 'tea' for gossip or truth, and 'shade' for a subtle insult. It inverts the more common 'no tea, no shade', which is used to soften a blunt remark. Where that phrase means 'no offence', 'all T, all shade' owns both the truth and the sting.$t$ where slug = 'all-t-all-shade' and status = 'active';
update public.unified_tags set short_description = $t$Japanese-style heated stone bath (ganbanyoku)$t$, description = $t$A dry heat bath, known in Japan as ganbanyoku, where bathers lie clothed on heated stone slabs to sweat, rather than bathing in water.$t$, long_description = $t$Bedrock baths are found in Japanese and Korean spas, onsen resorts and day spas: guests wear a light robe and lie on warm stone, often with a towel, then rest and rehydrate. They are a gentler alternative to a hot sauna. Many facilities have mixed-gender rooms because bathers stay clothed, though policies vary and some sessions are women-only.$t$ where slug = 'bedrock-bath' and status = 'active';
update public.unified_tags set short_description = $t$Slang meaning extremely$t$, description = $t$Slang used after a word as an intensifier, as in hungry boots or tired boots, meaning extremely.$t$, long_description = $t$The usage comes from Black queer and drag speech, as in 'slay the house down boots', and spread widely through social media. It works like a suffix of emphasis, standing in for 'very'.$t$ where slug = 'boots-slang-intensifier' and status = 'active';
update public.unified_tags set short_description = $t$Commanding officer role in role-play$t$, description = $t$An authority role-play persona of a ship's or military captain, used in naval, pirate and military-themed power exchange.$t$, long_description = $t$Captain scenes borrow naval or military hierarchy: orders, discipline and rank, sometimes paired with roles such as sailor, cadet or cabin boy. Sailor and naval uniforms are a long-standing part of gay fetish imagery.$t$ where slug = 'captain' and status = 'active';
update public.unified_tags set short_description = $t$Bi woman who dates only women$t$, description = $t$A bisexual woman who chooses to date only women while still experiencing attraction to men; short for female-exclusive bisexual female.$t$, long_description = $t$The label grew out of a February 2017 post on the Tumblr blog bi-women-confess asking whether 'female-exclusive bisexual' could be shortened to FEB. It distinguishes behaviour from attraction: a febfem remains bisexual even if she only partners with women. The term spread mainly in trans-exclusionary radical feminist circles, and many trans people and allies read it as a signal of transphobia.$t$ where slug = 'febfem' and status = 'active';
update public.unified_tags set short_description = $t$Gender-variant devotees of goddess Yellamma$t$, description = $t$Gender-variant devotees of the goddess Yellamma, found mainly in northern Karnataka and neighbouring parts of Maharashtra, Andhra Pradesh and Telangana, usually assigned male at birth and living as women.$t$, long_description = $t$Jogappas describe themselves as chosen by Yellamma to be her daughters. They sing devotional songs and perform priestly rituals, and locals seek their blessings against illness, misfortune and infertility. They are sometimes compared with Hijra communities but have their own religious tradition. Despite their ritual status, many face discrimination because of their gender identity.$t$ where slug = 'jogappa' and status = 'active';
update public.unified_tags set short_description = $t$1970s Boston gay visibility symbol$t$, description = $t$A gay rights symbol from 1970s Boston, created by artists Daniel Thaxton and Bernie Toale for a Gay Media Action-Advertising campaign.$t$, long_description = $t$The lavender rhinoceros debuted at Boston Pride in 1974 on shirts, pins and a life-sized papier-mâché figure, and ran on ads on the MBTA Green Line from December 1974 to February 1975. Toale said the rhino was chosen because 'it is a much maligned and misunderstood animal'. Lavender, a mix of pink and blue, stood for a merger of the feminine and masculine. It never became as widespread as the pink triangle or rainbow flag but remains a known piece of LGBTQ+ history.$t$ where slug = 'lavender-rhinoceros' and status = 'active';
update public.unified_tags set short_description = $t$Drag Race returnee who lip-syncs against the winner$t$, description = $t$A former Drag Race contestant brought back to lip-sync against the week's top queen on RuPaul's Drag Race All Stars; also fan slang for any performer who keeps winning lip-sync battles.$t$, long_description = $t$The Lip Sync Assassin format debuted on All Stars 5 in 2020 and returned on All Stars 6 and 8. If the All Star wins the lip-sync she eliminates a fellow queen; if the assassin wins, a group vote decides the elimination. Fans also use the label as a compliment for performers whose numbers combine precise mouthing, dance and showmanship.$t$ where slug = 'lip-sync-assassins' and status = 'active';
update public.unified_tags set short_description = $t$Diné gender role beyond man and woman$t$, description = $t$A Navajo (Diné) social and ceremonial role, traditionally for male-bodied people with a feminine nature who combine men's and women's work.$t$, long_description = $t$In Diné tradition, moving between men's and women's activities was considered normal, and some nádleehí were weavers, medicine people and ritual leaders, such as the weaver and healer Hosteen Klah. Colonial and missionary pressure later pushed the role into concealment, and recent Navajo Pride events have worked to reclaim it. The term is specific to Navajo culture and is related to, but not interchangeable with, the pan-Indigenous term Two-Spirit.$t$ where slug = 'nadleehi-navajo' and status = 'active';
update public.unified_tags set short_description = $t$Common genital bacterium, rarely a problem$t$, description = $t$A bacterium commonly found in the genital tract without causing problems, occasionally linked to urethritis and other infections.$t$, long_description = $t$Ureaplasma is passed on through sex but lives harmlessly in many sexually active people. Its role in conditions such as non-gonococcal urethritis is debated, and the European STI guidelines advise against routine testing or treatment for it, with or without symptoms. It is distinct from Mycoplasma genitalium, a related bacterium with a clearer link to disease.$t$ where slug = 'ureaplasma-urealyticum' and status = 'active';
update public.unified_tags set short_description = $t$Slang for a formerly gay man$t$, description = $t$Slang for a man who formerly identified as gay and now presents as straight.$t$, long_description = $t$Yestergay is a joking portmanteau of 'yesterday' and 'gay'. Green's Dictionary of Slang records it in the 2000s alongside 'hasbian', its counterpart for a woman who formerly identified as a lesbian. It is informal and can be dismissive.$t$ where slug = 'yestergay' and status = 'active';
update public.unified_tags set short_description = $t$Piauí, a state in north-eastern Brazil$t$, description = $t$Piauí (official abbreviation PI), a state in north-eastern Brazil whose capital is Teresina.$t$, long_description = $t$Piauí lies between Maranhão and Ceará, with a short Atlantic coastline and a semi-arid interior. Its capital, Teresina, is the largest city and has a small LGBTQ+ nightlife scene. Brazil has recognised same-sex marriage nationwide since 2013.$t$ where slug = 'pi-state' and status = 'active';
update public.unified_tags set short_description = $t$Place name in northern Germany$t$, description = $t$Place name shared by several villages in northern Germany, including Wustrow in the Mecklenburg Lake District, the Baltic resort of Wustrow on the Fischland peninsula, and Wustrow in the Wendland.$t$, long_description = $t$Wustrow in the Mecklenburg Lake District sits among lakes such as the Rätzsee and is a base for camping and canoeing. The Baltic resort of Wustrow lies between the sea and a lagoon on the Fischland-Darß-Zingst peninsula, and another Wustrow is a small town in the Wendland area of Lower Saxony.$t$ where slug = 'wustrow' and status = 'active';
update public.unified_tags set short_description = $t$Business and nightlife district of Lagos$t$ where slug = 'victoria-island' and status = 'active';
update public.unified_tags set short_description = $t$LGBTQ+ community in Salvador, Brazil$t$, description = $t$LGBTQ+ people, venues and community life in Salvador, the capital of Bahia, Brazil.$t$, long_description = $t$Salvador's queer scene sits alongside its Afro-Brazilian culture and one of the world's largest Carnivals, with bars and clubs around Barra and Rio Vermelho and an annual Pride. Brazil recognises same-sex marriage, but anti-LGBTQ+ violence remains a concern, so local advice is useful.$t$ where slug = 'salvador-lgbtq' and status = 'active';
