do $merge$
declare v_src uuid; v_tgt uuid;
begin
  select id into v_src from public.unified_tags where slug = 'decoration' and status = 'active';
  select id into v_tgt from public.unified_tags where slug = 'interior-design' and status = 'active';
  if v_src is not null and v_tgt is not null then
    update public.tag_category_assignments set is_primary = false where tag_id = v_src and is_primary;
    perform public.merge_tag_concept(v_tgt, v_src, 'migration:99991792852555', 'excel-review-batch14-2026-10-23');
    update public.tag_aliases set canonical_tag_id = v_tgt where canonical_tag_id = v_src;
  end if;
end
$merge$;

create temp table _b14_dep on commit drop as
select t.id, t.slug, r.why, false as used
from (values
('aposexual', $t$no attested meaning in this sense, or out of scope for the glossary$t$),
('heterotypical', $t$not an orientation or gender label (a sexology adjective), and unused$t$),
('switchuationship', $t$no attested meaning in this sense, or out of scope for the glossary$t$),
('the-question-of-gender', $t$no attested meaning in this sense, or out of scope for the glossary$t$),
('bio-king-faux-king', $t$no attested meaning in this sense, or out of scope for the glossary$t$),
('boner-donor', $t$no attested meaning in this sense, or out of scope for the glossary$t$),
('core-bdsm', $t$no attested meaning in this sense, or out of scope for the glossary$t$),
('doris-day', $t$no attested meaning in this sense, or out of scope for the glossary$t$),
('horatian', $t$no attested meaning in this sense, or out of scope for the glossary$t$),
('partners-in-mischief', $t$no attested meaning in this sense, or out of scope for the glossary$t$),
('pharaoh', $t$no attested meaning in this sense, or out of scope for the glossary$t$),
('potty-princess', $t$no attested meaning in this sense, or out of scope for the glossary$t$),
('quacking', $t$no attested meaning in this sense, or out of scope for the glossary$t$),
('spongeworthy', $t$no attested meaning in this sense, or out of scope for the glossary$t$),
('zoophilia', $t$no attested meaning in this sense, or out of scope for the glossary$t$),
('hellpuppy', $t$unused, and no suitable active tag to merge it into$t$),
('microphone', $t$unused, and no suitable active tag to merge it into$t$),
('spill', $t$unused, and no suitable active tag to merge it into$t$),
('tinkerbelle', $t$unused, and no suitable active tag to merge it into$t$)
) r(slug, why)
join public.unified_tags t on t.slug = r.slug
where t.status = 'active'
  and coalesce(t.usage_count, 0) = 0
  and not exists (select 1 from public.unified_tag_assignments a where a.tag_id = t.id)
  and not exists (select 1 from public.unified_tags m where m.merged_into_id = t.id);

insert into _b14_dep
select t.id, t.slug, case when t.slug = 'lgbtq-unknown'
         then 'empty import placeholder with no meaning'
         when t.slug = 'bestiality'
         then 'not queer or kink vocabulary; a glossary page for it echoes the slur linking queerness with bestiality'
         else 'its only uses were accidental word matches on unrelated items' end, true
from public.unified_tags t
where t.slug = any (array['angel', 'zombie', 'goat', 'frog', 'delta', 'little-thing', 'maestro', 'slasher', 'uncle', 'devotee', 'brother', 'board-member', 'host', 'guide', 'giving', 'shapeshifter', 'vixen', 'pirate', 'lgbtq-unknown', 'bestiality'])
  and t.status = 'active'
  and not exists (select 1 from public.unified_tags m where m.merged_into_id = t.id);

delete from public.unified_tag_assignments a using _b14_dep d where a.tag_id = d.id and d.used;

update public.unified_tags t
   set status = 'deprecated', deprecated_at = now(), seo_indexable = false, usage_count = 0,
       deprecation_reason = 'Review queue 2026-10-23: ' || d.why
  from _b14_dep d where t.id = d.id;

create temp table _b14_keep_out (slug text primary key) on commit drop;
insert into _b14_keep_out values ('anthropologist'),('attila-horbiger'),('clown'),('conductor'),('jan-mikolasek');

update public.tag_suggestions g
   set status = 'rejected', reviewed_at = now(),
       metadata = coalesce(g.metadata, '{}'::jsonb) || jsonb_build_object(
         'resolution',
           case when d.id is not null then 'deprecated: ' || d.why
                when t.status = 'merged' then 'merged into interior-design'
                else 'checked: definition verified or corrected' end,
         'resolved_by', 'migration:99991792852555')
  from public.unified_tags t
  left join _b14_dep d on d.id = t.id
 where g.entity_id = t.id and g.entity_type = 'tag'
   and g.source = 'excel_review_2026_10_23' and g.status = 'pending'
   and g.metadata->>'review_type' = 'Verify facts / meaning'
   and t.slug not in (select slug from _b14_keep_out);

do $verify$
declare v_bad int; v_left text;
begin
  select count(*) into v_bad from _b14_dep d join public.unified_tags t on t.id = d.id
   where t.status <> 'deprecated' or t.seo_indexable;
  if v_bad <> 0 then raise exception 'batch14: % tags not cleanly deprecated', v_bad; end if;

  select count(*) into v_bad from public.unified_tag_assignments a join _b14_dep d on d.id = a.tag_id;
  if v_bad <> 0 then raise exception 'batch14: % assignments still point at deprecated tags', v_bad; end if;

  if (select count(*) from _b14_dep where used) < 15 then
    raise exception 'batch14: only % word-match tags were deprecated', (select count(*) from _b14_dep where used);
  end if;

  select count(*) into v_bad from public.unified_tags
   where status = 'active' and slug = any (array['amateur', 'axel-hotel-partner', 'bike-related', 'copacabana', 'cranbrook', 'durango', 'georgetown', 'georgia', 'german-business', 'icelandic', 'influence', 'midwest-pride', 'paradise-location', 'paradise-location', 'peaches', 'platforms', 'queer-named', 'registration', 'san-jose', 'santa-cruz', 'tennis-themed', 'thai-business', 'turkish'])
     and long_description ~* '(should be (confirmed|checked)|a reviewer should|check which (city|place)|may need checking|might be better replaced|more concrete tags)';
  if v_bad <> 0 then raise exception 'batch14: % bodies still carry an editor-facing sentence', v_bad; end if;

  if exists (select 1 from public.unified_tags where slug = 'captain' and wikidata_id = 'Q19100') then
    raise exception 'batch14: captain still carries the army-rank identifier';
  end if;

  if exists (select 1 from public.unified_tags where slug = 'pi-state' and status = 'active'
              and short_description not like 'Piauí%') then
    raise exception 'batch14: pi-state was not corrected';
  end if;

  select string_agg(t.slug, ',') into v_left from public.tag_suggestions g join public.unified_tags t on t.id = g.entity_id
   where g.entity_type = 'tag' and g.source = 'excel_review_2026_10_23' and g.status = 'pending'
     and g.metadata->>'review_type' = 'Verify facts / meaning'
     and t.slug not in ('anthropologist','attila-horbiger','clown','conductor','jan-mikolasek')
     and t.status <> 'active';
  if v_left is not null then raise exception 'batch14: rows for retired tags still pending: %', v_left; end if;
end
$verify$;
